class EarCheckTest(unittest.TestCase):
    """DESIGN.md 6-10 の (5)・G-15：確かめない型の答えは、会話AIの聞き取りと別の耳の文字を比べ、食い違えば意味を確かめる。
    ⛔ G-14 の残りの誤り：「してないです」を会話AIが「捨てないです」と聞いてAIが「はい」を選んだ・「いや、これから」を「や、これから」と聞いて
    「している」を選んだ（どちらも、別の耳は正しく聞いた）。"""

    def flow(self, required=True):
        from flowctl import Flow, Question
        return Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"), required=required,
                              meanings=AmbiguousAnswerTest.M),
                     Question("Q2", "ご希望の日時をお聞かせいただけますでしょうか？", "datetime", conditions=("答えた",))])

    def answer(self, f, heard, ear, cond):
        f.on_callee(); f.on_heard(heard)
        self.assertTrue(f.wants_checks("record_answer", {"question_id": "Q1", "condition_id": cond}))
        f.on_check("ear", ear)
        return f.apply("record_answer", {"question_id": "Q1", "condition_id": cond, "value": heard})

    def test_alike(self):
        from flowctl import heard_alike
        for a, b in (("家まだしていません。", "いえ、まだしていません。"), ("いいえ、まだです。", "いえ、まだです。"), ("はい、予約しています。", "はい予約しています"),
                     ("いや、これからなんです。", "いいえ、これからなんです。"),
                     # 頭の返事の言葉の伸ばし方の違い（2026-10-17：AmiVoice は「えー」「いやあ」と書く）
                     ("ええ、してます。", "えーしてます。"), ("いや、これからなんです。", "いやあ、これからなんです。"), ("いいえ、まだです。", "いえまだです。"),
                     # 答えの前の言いよどみ（AmiVoice は息の音を「あ」と書く）
                     ("はい、予約しています。", "あはい。予約しています。"), ("まだです。", "えーと、まだです。"), ("してないです。", "あのー、してないです。")):
            self.assertTrue(heard_alike(a, b), (a, b))
        for a, b in (("捨てないです。", "してないです。"), ("や、これからなんです。", "いや、これからなんです。"), ("はい、清掃しました。", "はい、先週しました。"),
                     ("や、これからなんです。", "いやあ、これからなんです。"), ("いいえ、まだです。", "はい、まだです。"), ("ええ、してます。", "いえ、してます。"),
                     ("いいえ、まだです。", "あ、はい、まだです。"), ("ありがとうございます。", "りがとうございます。")):
            self.assertFalse(heard_alike(a, b), (a, b))

    def test_disagreement_is_confirmed(self):
        f = self.flow()
        r = self.answer(f, "捨てないです。", "してないです。", "はい")
        self.assertEqual((r["result"], f.awaiting_confirm), ("confirm_required", "Q1"))
        self.assertIn("ご予約はお済みということ", r["say"])                  # 意味の言葉で確かめる（曖昧な答えと同じ道）
        self.assertTrue(any("別の耳" in why for _, _, why in f.items["Q1"].history))

    def test_agreement_or_no_ear_is_taken(self):
        for ear in ("いいえ、まだです。", None):                             # 同じこと・別の耳が間に合わなかった（比べない＝止まらない）
            f = self.flow()
            r = self.answer(f, "いえ、まだです。", ear, "いいえ")
            self.assertEqual((r["result"], f.items["Q1"].state), ("next", "accepted"), ear)

    def test_not_required_is_unresolved(self):
        f = self.flow(required=False)
        r = self.answer(f, "捨てないです。", "してないです。", "はい")
        self.assertEqual(f.items["Q1"].state, "unresolved")                 # 必須でない項目は確かめない（曖昧な答えと同じ）

    def test_which_reports_wait(self):
        # 返事を作る前に確かめを待つのは、答えをそのまま受け取りうる報告だけ（DESIGN.md 1章）
        # 答えの段の報告は、こちらへ尋ねた言葉かが判定の読みで決まる（flowctl.queries_us）ので、尋ねられたときに止める報告は、どれも判定が届いてから当てる
        # （✅ 2026-11-08 日本時間8時55分08秒「(イ)」。⛔ それまでは値を聞く型の最初の答え・言い直しを待っていないときの言い直しへの返事は待たなかった）
        f = self.flow()
        self.assertTrue(f.wants_checks("record_answer", {"質問": "Q1", "答えの種類": "はい"}))
        self.assertTrue(f.wants_checks("confirm_field", {"質問": "Q1"}))
        f.current = "Q2"
        self.assertTrue(f.wants_checks("record_answer", {"質問": "Q2", "答えの種類": "答えた"}))
        self.assertFalse(f.wants_checks("request_end", {"reason": "done"}))   # 電話を終える報告は止めない（判定を待つかは電話を終える決まりのまま）
        self.assertTrue(f.wants_checks("record_answer", {"質問": "Q2", "答えの種類": "わからない"}))  # 「わからない」はそのまま受け取る
        f.awaiting_confirm = "Q2"
        self.assertTrue(f.wants_checks("confirm_field", {"質問": "Q2"}))   # 言い直しへの返事
        self.assertTrue(f.wants_checks("replay_opening", {"流し直す部分": "代わった方へ"}))  # 取り次ぎを待つ間に流さない
        # 答えの段の名乗りの流し直しも、判定が届いてから当てる（こちらへ尋ねた言葉かは判定の読みで決まる＝✅ 2026-11-08 日本時間8時55分08秒「(イ)」）
        self.assertTrue(f.wants_checks("replay_opening", {"流し直す部分": "名乗り"}))
        f.on_check("ear", "はい")
        f.on_callee()
        self.assertIsNone(f.ear_said)                                       # 相手の発話ごとに消える


class MeaningJudgeTest(unittest.TestCase):
    """DESIGN.md 6-10 の (6)・G-53：答えの意味は、会話AIとは別の文字のAI（意味の判定）の確かな読みで決める（会話AIの選んだ答えは使わない）。
    ⛔ 2026-10-17 ユーザー：「精度は100％にする仕組みを作らないとだめですよ。間違えるのが当たり前でスルーしてるだろ！」＝記録の通話で、
    意味を取り違えた答え12回を、流れの制御が確かめずに受け取っていた。
    ✅ 2026-11-08 日本時間12時11分40秒 ユーザー：「そもそも会話 AI がなぜ判定に加わっているんですか？会話 AI の判定は当てにならないというのは、以前から
    分かっていることだから判定 AI を入れたんですよね。それを判定 AI と一致する時ということにしたら精度が下がるに決まってるじゃないですか。」
    ⛔ それまでのこの組の試験は「判定が会話AIの選んだ答えと食い違えば確かめる（会話AIの答えで言い直すこともある）」を確かめていた＝会話AIを判定の1つとして
    残した形。いまは、判定の確かな読みがあれば、会話AIがどの答えを報告しても同じ動き（HedgedSalesTest.test_judges_decide_the_answer_whatever_the_conversation_ai_reports）"""
    M = {"はい": "ご予約はお済みということ", "いいえ": "ご予約はまだということ"}

    def flow(self):
        from flowctl import Flow, Question
        return Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"), meanings=self.M),
                     Question("Q2", "お支払いはカードと振込のどちらがよろしいでしょうか？", "choice", conditions=("カード", "振込"))])

    @staticmethod
    def report(f, qid, heard, cond, meaning):
        f.on_callee(); f.on_heard(heard); f.on_check("judge", meaning)
        return f.apply("record_answer", {"question_id": qid, "condition_id": cond, "value": heard})

    @staticmethod
    def reply(f, qid, heard, result, meaning, correction=None):
        f.on_callee(); f.on_heard(heard); f.on_check("judge", meaning)
        return f.apply("confirm_field", {"question_id": qid, "result": result, **({"correction": correction} if correction else {})})

    def to_q2(self, f):
        self.report(f, "Q1", "はい、予約しています。", "はい", "はい")
        self.assertEqual(f.current, "Q2")

    def test_dont_know_but_judge_cannot_decide_asks_again(self):
        # ⛔ 2026-10-19 G-55：「10名未満ではないです」（3択）をAIは「わからない」、判定は「決められない」＝答えの一部を言っている ⇒ 聞き直す
        f = self.flow()
        self.to_q2(f)
        r = self.report(f, "Q2", "振込じゃないほうがいいかなとは思いますけど", "unknown", "決められない")
        self.assertEqual(r["result"], "ask_back")
        self.assertEqual(f.items["Q2"].state, "unclear")
        f = self.flow()
        self.to_q2(f)
        self.report(f, "Q2", "ちょっと分からないです。", "unknown", "unknown")       # 判定もわからない ⇒ そのまま受け取る
        self.assertEqual(f.items["Q2"].state, "dont_know")
        # 会話AIの「答えたくない」は決めに使わない（✅ 2026-11-08 日本時間12時11分40秒）：判定が確かに「決められない」と読めば、答えたくないとは受け取らずに
        # 質問から聞き直す・判定が確かに「答えたくない」と読めば、会話AIが「わからない」と報告しても答えたくない（二度と聞かない）。⛔ それまでは会話AIの
        # 「答えたくない」を判定に当てずに受け取っていた（会話AIの読み違いで、伺える答えを二度と伺わなくなる形）
        f = self.flow()
        self.to_q2(f)
        r = self.report(f, "Q2", "それはちょっと言えないです。", "refused", "決められない")
        self.assertEqual((r["result"], f.items["Q2"].state), ("ask_back", "unclear"))
        f = self.flow()
        self.to_q2(f)
        self.report(f, "Q2", "それはちょっと言えないです。", "unknown", "refused")
        self.assertEqual(f.items["Q2"].state, "refused")

    def test_agree_is_taken(self):
        f = self.flow()
        self.report(f, "Q1", "はい、予約しています。", "はい", "はい")
        self.assertEqual(f.items["Q1"].state, "accepted")

    def test_unknown_report_with_an_answer_takes_the_judges_answer(self):
        # 「いや、これからなんです」をAIが「わからない」：判定は確かに「いいえ」（言い切っている）⇒ 判定の答えで受け取る（✅ 2026-11-08 日本時間12時11分40秒＝
        # 会話AIは判定に加えない。⛔ 2026-10-17 から 11-08 12時台までは、会話AIの報告と食い違うので判定の意味で言い直していた。その前は確かめずに「-」）
        f = self.flow()
        r = self.report(f, "Q1", "いや、これからなんです。", "unknown", "いいえ")
        self.assertEqual((r["result"], r["question_id"], f.items["Q1"].state, f.items["Q1"].condition), ("next", "Q2", "accepted", "いいえ"))

    def test_not_decided_yet_is_read_by_the_judge_not_the_ai(self):
        # 「まだ決めてないです」をAIが「どちらでも」：判定は「わからない」⇒ 会話AIの「どちらでも」は使わず、最初の答えの「まだ決めていない」として選ぶ助け
        # （✅ 2026-11-07 日本時間22時02分54秒の (イ)・11-08 12時11分40秒。⛔ それまでは会話AIの「どちらでも」で「…どちらでも構わない…」と言い直していた）
        from phrases import ACK, HESITATE_POINT
        f = self.flow()
        f.use_checks("judge")
        self.to_q2(f)
        r = self.report(f, "Q2", "まだ決めてないです。", "any", "unknown")
        heard = ACK.get(r.get("ack"), "") + "".join(p["text"] for p in r.get("play") or []) + (r.get("say") or "")
        self.assertEqual((r["result"], heard, f.items["Q2"].condition), ("hesitate", "はい、" + HESITATE_POINT, None))

    def test_either_is_taken_from_the_judge_whatever_the_ai_chose(self):
        # 「どちらでも大丈夫です」をAIが「カード」：判定は確かに「どちらでも」⇒ 「どちらでも」で受け取る（会話AIの「カード」は渡らない。⛔ 11-08 12時台までは
        # 会話AIの報告と食い違うので言い直していた）
        from flowctl import ANY
        f = self.flow()
        self.to_q2(f)
        self.report(f, "Q2", "どちらでも大丈夫です。", "カード", ANY)
        self.assertEqual((f.items["Q2"].state, f.items["Q2"].condition, f.export()["Q2"]), ("accepted", ANY, "どちらでも"))

    def test_undecided_is_not_restated_with_the_ais_choice(self):
        # 判定が確かに「決められない」と読んだ「そうですね。」：会話AIの選んだ「はい」を言い直す候補にしない（✅ 2026-11-08 日本時間12時11分40秒）＝目的に進む
        # 向きが1つに決まらない質問なので、聞き取れているとして質問から聞き直す（_undecided_answer・_ask_kind。⛔ それまでは会話AIの「はい」で
        # 「念のためご予約はお済みということでよろしいでしょうか？」と言い直していた）
        from flowctl import UNDECIDED
        from phrases import ACK
        f = self.flow()
        r = self.report(f, "Q1", "そうですね。", "はい", UNDECIDED)
        self.assertEqual((r["result"], ACK[r["ack"]], f.items["Q1"].condition), ("ask_back", "はい、", None))
        self.assertNotIn("ご予約はお済み", str(r))

    def test_no_choice_is_asked_back_by_the_judges_reading(self):
        # 判定が確かに「決められない」と読めば、会話AIが「わからない」と報告しても「わからない」とは受け取らず、聞き返しの回数の中で質問から聞き直す
        # （⛔ 11-08 12時台までは、2回目の会話AIの「わからない」を受け取っていた＝会話AIの報告で答えが決まる形）。判定が確かに「わからない」と読めば受け取る
        from flowctl import UNDECIDED
        f = self.flow()
        self.assertEqual(self.report(f, "Q1", "ちょっとわからないです。", "unknown", UNDECIDED)["result"], "ask_back")
        self.assertEqual(self.report(f, "Q1", "ちょっとわからないです。", "unknown", UNDECIDED)["result"], "ask_back")
        self.assertEqual(f.items["Q1"].state, "unclear")
        g = self.flow()
        self.report(g, "Q1", "ちょっとわからないです。", "はい", "unknown")
        self.assertEqual(g.items["Q1"].state, "dont_know")

    def test_no_judgment_keeps_the_old_way(self):
        f = self.flow()
        self.report(f, "Q1", "はい、予約しています。", "はい", None)
        self.assertEqual(f.items["Q1"].state, "accepted")

    def test_unchecked_counts_only_the_judgments_issued_for_that_utterance(self):
        # F0（✅ 2026-11-07 日本時間8時57分04秒）：答えの段でその場の判定を使わない（meaning_judge.UNUSED_IN）と、その発話には組（judge2）だけを出す。
        # 届かなかった確かめ（unchecked＝通話後の検証へ回す答え）は、その発話に出した判定（電話接続側の on_judging）だけを数える。⛔ F0 の地図で見つけた：
        # 通話で使う確かめ（use_checks）の全部を数えていたので、出していない judge を毎回「届かなかった」とし、どの答えも通話後の検証へ回る形だった。
        # 1つも出していない発話（判定を出す前に受け取った）は、今までどおり使う判定の全部が届かなかった
        f = self.flow()
        f.use_checks("judge", "judge2")
        f.on_callee(); f.on_judging("judge2"); f.on_heard("はい、予約しています。"); f.on_check("judge2", "はい")
        f.apply("record_answer", {"question_id": "Q1", "condition_id": "はい", "value": "はい、予約しています。"})
        self.assertEqual((f.items["Q1"].state, f.unchecked()), ("accepted", {}))
        # 判定の読みが1つも無いまま受け取る答え（「わからない」＝依頼者へは「-」）は、使う判定の全部が届かなかった
        f = self.flow()
        f.use_checks("judge", "judge2")
        f.on_callee(); f.on_heard("ちょっと分からないです。")
        f.apply("record_answer", {"question_id": "Q1", "condition_id": "unknown"})
        self.assertEqual(f.unchecked(), {"Q1": ["judge", "judge2"]})

    def test_decided_once_within_the_wait(self):
        # F0（✅ 2026-11-07 日本時間8時57分04秒「はい、その形でいいですが…」＝答えの段は、d1-ultra と Jev を同時に出し、待つ長さ（2秒）の中で1回だけ決め、
        # あとから覆す道を外す・2秒を超えた読みは通話後の確かめ。3時14分01秒「後から判定が覆ること自体が正しい設定ならないんじゃないですか」）
        # (1) 決めた（電話接続側が待つのをやめた＝on_decided・答えを受け取った）あとに届いたその発話の読みは、答えにも返事にも当てず、記録だけ（通話後の確かめ）。
        #     ⛔ 直す前：遅れて届いた食い違いで受け取った答えを「-」にし、締めの前に「お声が聞き取れませんでしたので…」で伺い直した
        from meaning_judge import Reading
        f = self.flow()
        f.use_checks("ear", "judge2")
        f.on_callee(); f.on_judging("judge2"); f.on_heard("はい、予約しています。"); f.on_check("judge2", Reading("はい"))
        f.on_decided()
        r = f.apply("record_answer", {"question_id": "Q1", "condition_id": "はい"})
        self.assertEqual((r["result"], r["question_id"], f.export()["Q1"]), ("next", "Q2", "はい"))
        f.on_check("ear", "いいえ、まだしていません。", turn=1)
        self.assertEqual((f.items["Q1"].state, f.export()["Q1"], f.recheck_queue), ("accepted", "はい", []))
        self.assertEqual(f.taken["Q1"]["late"], {"ear": "いいえ、まだしていません。"})
        self.assertEqual(f.unchecked(), {"Q1": ["ear"]})                   # 通話後の確かめが、記録の読みと録音で確かめる
        # (2) 期限までに判定の確かな読みが無い（組が確かに読めなかった・間に合わなかった）：その場で確かめる（受け取らない）。期限のあとに届いた読みは使わない。
        #     「決められない」の読みは作らない（尋ねた・まだ決めていない・迷っているの決まりに読まれない）
        f = self.flow()
        f.use_checks("judge2")
        f.on_callee(); f.on_judging("judge2"); f.on_heard("はい、予約しています。")
        f.on_decided()
        f.on_check("judge2", Reading("はい"))                              # 期限のあと、報告を受ける前に届いた
        r = f.apply("record_answer", {"question_id": "Q1", "condition_id": "はい"})
        self.assertEqual((r["result"], f.items["Q1"].state), ("confirm_required", "checking"))   # 確かめ中（受け取っていない）
        self.assertIn("ご予約はお済みということ", r["say"])
        self.assertNotIn("judge2", f.check)
        f.on_callee(); f.on_judging("judge2"); f.on_heard("はい、そうです。"); f.on_check("judge2", Reading("はい"))   # 選ぶ型の言い直しへの返事は選択肢で読む
        f.on_decided()
        r = f.apply("confirm_field", {"question_id": "Q1", "result": "affirmed"})
        self.assertEqual((r["result"], f.export()["Q1"]), ("next", "はい"))
        # 「わからない」「答えたくない」（依頼者へは「-」「✕」＝誤った値は渡らない）は、判定の読みが無くても受け取る（答えたくないは二度と伺わない）
        f = self.flow()
        f.use_checks("judge2")
        f.on_callee(); f.on_judging("judge2"); f.on_heard("それは言えないです。")
        f.on_decided()
        r = f.apply("record_answer", {"question_id": "Q1", "condition_id": "refused"})
        self.assertEqual((r["result"], f.items["Q1"].state), ("next", "refused"))

    def test_missed_judgment_on_an_optional_question_is_left_to_the_check_after_the_call(self):
        # F0 の (2) を必須でない質問に当てるとき（2026-11-08 日本時間10時台に流れの制御に通して見つけた）：決める時に判定の確かな読みが無いことを、その場で
        # 確かめる理由（MISSED_WHY）にしていたので、必須でない質問は「確かめない決まり（6-11：必須でない項目は聞き返さず「-」）」の道へ流れ、会話AIの答えを
        # 捨てて「-」にしていた（F0 の前は、判定がまだ届いていない答えを受け取り、届かなければ通話後の確かめへ回していた）
        # ⇒ その場で確かめるのは、伺い直す質問（必須・その場で1回だけ伺い直す質問）だけ。必須でない質問は受け取り、届かなかった確かめ（unchecked）として
        #    通話後の確かめが録音でやり直す（やり直せなければ「-」＝DESIGN.md 6-12）＝確かめを増やさず（6-11）、答えも捨てない
        from flowctl import Flow, Question
        f = Flow([Question("Q1", "パンフレットをお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"), required=False),
                  Question("Q2", "ご希望の日時をお聞かせいただけますでしょうか？", "datetime", conditions=("答えた",))], play_recordings=True)
        f.use_checks("judge", "judge2")
        f.on_callee(); f.on_judging("judge"); f.on_judging("judge2"); f.on_heard("はい、お願いします。")
        f.on_decided()
        r = f.apply("record_answer", {"question_id": "Q1", "condition_id": "はい"})
        self.assertEqual((r["result"], r["question_id"], f.items["Q1"].state), ("next", "Q2", "accepted"))
        self.assertEqual(f.unchecked(), {"Q1": ["judge", "judge2"]})

    def test_late_clash_is_recorded_only(self):
        # F0（2026-11-08 日本時間9時台）：受け取ったあとに届いて食い違った判定は、答えにも返事にも当てず、受け取った答えの記録（late）に残すだけ。依頼者へ渡す値・
        # いまの質問・締めの前の確認の並びは変わらず、届かなかった確かめ（unchecked）に数えて、通話後の確かめが録音で確かめる。
        # ⛔ F0 の前は、依頼主へ渡さず（「-」）・締めの前の念のための確認で、もう一度聞いていた
        f = self.flow()
        f.use_checks("judge")
        r = self.report(f, "Q1", "これからなんです。", "はい", None)      # 判定がまだ届いていない
        self.assertEqual((r["result"], r["question_id"], f.items["Q1"].state), ("next", "Q2", "accepted"))
        self.assertEqual(f.unchecked(), {"Q1": ["judge"]})              # 届かなければ通話後の検証へ
        f.on_check("judge", "いいえ")                                   # 同じ相手の発話の判定が、受け取ったあとに届いた
        self.assertEqual((f.items["Q1"].state, f.export()["Q1"], f.current, f.recheck_queue), ("accepted", "はい", "Q2", []))
        self.assertEqual(f.taken["Q1"]["late"], {"judge": "いいえ"})
        self.assertEqual(f.unchecked(), {"Q1": ["judge"]})              # 遅れた読みは、届かなかった確かめのまま
        r = self.report(f, "Q2", "カードでお願いします。", "カード", "カード")
        self.assertEqual((r["result"], f.export()), ("end", {"Q1": "はい", "Q2": "カード"}))   # 締めの前に伺い直さない

    def test_late_agreement_changes_nothing(self):
        # F0（2026-11-08 日本時間9時台）：同じ読みで遅れて届いても、記録（late）に残すだけ。受け取った時に決めた答えなので、届かなかった確かめに数える
        # （⛔ F0 の前は、遅れた読みを受け取った答えに当て直し、届いた確かめとして数えた）
        f = self.flow()
        f.use_checks("judge")
        self.report(f, "Q1", "はい、予約しています。", "はい", None)
        f.on_check("judge", "はい")
        self.assertEqual((f.items["Q1"].state, f.export()["Q1"], f.taken["Q1"]["late"], f.unchecked()),
                         ("accepted", "はい", {"judge": "はい"}, {"Q1": ["judge"]}))

    def test_late_check_belongs_to_its_utterance(self):
        # 遅れて届いた確かめは、その相手の発話への報告で受け取った項目の記録にだけ残す（あとの発話・聞き直したあとの答えには残さない）。
        # F0（2026-11-08 日本時間9時台）：記録だけ＝どちらの答えも変えない（⛔ F0 の前は、Q1 を「-」にしていた）
        f = self.flow()
        self.report(f, "Q1", "はい、予約しています。", "はい", None)
        old = f.callee_turns
        self.report(f, "Q2", "カードでお願いします。", "カード", "カード")
        f.on_check("judge", "いいえ", turn=old)                       # Q1 の発話の判定（遅れた）
        self.assertEqual((f.items["Q1"].state, f.items["Q2"].state, f.export()), ("accepted", "accepted", {"Q1": "はい", "Q2": "カード"}))
        self.assertEqual(f.taken["Q1"]["late"], {"judge": "いいえ"})
        f.on_check("judge", "振込", turn=old)                         # Q2 は別の発話で受け取った ⇒ Q2 の答えにも記録にも当てない
        self.assertEqual((f.items["Q2"].state, f.export()["Q2"], "late" in f.taken["Q2"]), ("accepted", "カード", False))
        self.assertEqual(f.meaning_said, "カード")                      # いまの発話の判定は、古い発話の判定で書き換えない

    def test_late_ear_clash_is_recorded_only(self):
        # 別の耳の文字が遅れて届いて食い違った ⇒ 判定と同じ扱い（どの確かめも、遅れたら同じ決まり）。F0（2026-11-08 日本時間9時台）：答えには当てず記録（late）
        # だけ・届かなかった確かめに数えて、通話後の確かめが録音で確かめる（⛔ F0 の前は、依頼者へ渡さず「-」にしていた）
        f = self.flow()
        f.use_checks("judge", "ear")
        self.report(f, "Q1", "捨てないです。", "はい", "はい")
        f.on_check("ear", "してないです")
        self.assertEqual((f.items["Q1"].state, f.export()["Q1"], f.current), ("accepted", "はい", "Q2"))
        self.assertEqual((f.taken["Q1"]["late"], f.unchecked()), ({"ear": "してないです"}, {"Q1": ["ear"]}))

    def test_late_clash_during_recheck_is_recorded_only(self):
        # 締めの前の念のための確認の最中に、遅れて届いて食い違った。F0（2026-11-08 日本時間9時台）：受け取った答え・確認の並び・いまの質問は変えず、記録（late）
        # だけ（⛔ F0 の前は、受け取った答えを「-」にして確認の並びに足していた）
        f = self.flow()
        self.report(f, "Q1", "はい、予約しています。", "はい", None)
        f.phase, f.current = "rechecking", "Q2"
        f.on_check("judge", "いいえ")
        self.assertEqual((f.items["Q1"].state, f.export()["Q1"], f.recheck_queue, f.current, f.phase), ("accepted", "はい", [], "Q2", "rechecking"))
        self.assertEqual(f.taken["Q1"]["late"], {"judge": "いいえ"})

    def test_confirm_reply_is_checked_like_an_answer(self):
        # 言い直しへの返事も、最初の答えと同じ確かめに当てる：AIは「合っている」、判定は別の選択肢 ⇒ 判定の意味で、もう1回だけ言い直す
        f = self.flow()
        self.report(f, "Q1", "大丈夫です。", "はい", "はい")                # 曖昧な答え ⇒ 言い直して確かめる
        self.assertEqual(f.awaiting_confirm, "Q1")
        r = self.reply(f, "Q1", "あ、いえ、まだなんです。", "affirmed", "いいえ")
        self.assertEqual((r["result"], f.items["Q1"].condition), ("confirm_required", "いいえ"))
        self.assertIn("ご予約はまだということ", r["say"])
        r = self.reply(f, "Q1", "えっと、どうだったかな。", "affirmed", "はい")  # また食い違う（AIは「いいえ」で合っている、判定は「はい」）
        self.assertEqual((f.items["Q1"].state, f.export()["Q1"]), ("unresolved", "-"))   # 言い直しは1回まで ⇒「-」

    def test_value_confirm_reply_is_checked(self):
        # 値を聞く型：AIは「合っている」、判定は「決められない」⇒ もう1回だけ言い直す。判定が「合っている」なら確かめ済み
        from flowctl import Flow, Question, UNDECIDED
        f = Flow([Question("Q1", "ご希望の日時をお聞かせいただけますでしょうか？", "datetime", conditions=("答えた",))])
        f.on_callee(); f.on_heard("16日の午後2時で。")
        f.apply("record_answer", {"question_id": "Q1", "condition_id": "答えた", "value": "16日の午後2時"})
        r = self.reply(f, "Q1", "うーん、たぶん。", "affirmed", UNDECIDED)
        self.assertEqual((r["result"], f.items["Q1"].state), ("confirm_required", "checking"))
        r = self.reply(f, "Q1", "はい、それで大丈夫です。", "affirmed", "affirmed")
        self.assertEqual(f.items["Q1"].state, "confirmed")
        g = Flow([Question("Q1", "ご希望の日時をお聞かせいただけますでしょうか？", "datetime", conditions=("答えた",))])
        g.on_callee(); g.on_heard("16日の午後2時で。")
        g.apply("record_answer", {"question_id": "Q1", "condition_id": "答えた", "value": "16日の午後2時"})
        # 合っているか・違う値かは判定が決める（✅ 2026-11-08 日本時間12時11分40秒）：判定が確かに「違う値を言われた」と読めば、会話AIの直した値の文字でもう一度
        # 言い直して確かめる（値はお客様ご本人の「はい」で確かめる）。判定が確かに「合っている」と読めば、会話AIが「違う値」と報告しても確かめ済み
        # （⛔ 11-08 12時台までは、会話AIの「違う値」で言い直していた）
        r = self.reply(g, "Q1", "いや、17日です。", "corrected", "corrected", correction="17日の午後2時")
        self.assertEqual((r["result"], g.items["Q1"].value), ("confirm_required", "17日の午後2時"))
        h = Flow([Question("Q1", "ご希望の日時をお聞かせいただけますでしょうか？", "datetime", conditions=("答えた",))])
        h.on_callee(); h.on_heard("16日の午後2時で。")
        h.apply("record_answer", {"question_id": "Q1", "condition_id": "答えた", "value": "16日の午後2時"})
        r = self.reply(h, "Q1", "はい、それでお願いします。", "corrected", "affirmed", correction="17日の午後2時")
        self.assertEqual((h.items["Q1"].state, h.items["Q1"].value), ("confirmed", "16日の午後2時"))

    def test_hold_is_not_an_answer(self):
        # 取り次ぎを待つように言われた：答えとして受け取らず、「はい、」の相づちのあと、AIは黙って待つ（差し戻しではない＝張り替えない）。
        # ✅ 2026-11-06 日本時間2時28分41秒 ユーザー：「お客様：ちょっと待ってもらえますか。も、黙って待つはおかしいと思いますよ。「はい、」のような
        # 相づちがないと失礼です。」（⛔ それまでは「相手はいま聞いていない」として相づちも流さなかった）
        from flowctl import HANDOVER, HOLD
        f = self.flow()
        r = self.report(f, "Q1", "担当に代わりますので少々お待ちください。", "はい", HOLD)
        self.assertEqual((r["result"], r["ack"], f.items["Q1"].state, f.current), ("hold", "hai", "empty", "Q1"))
        self.assertTrue(f.holding)                                        # 電話接続側は、黙っている秒の見張りを止める
        r = self.report(f, "Q1", "お電話代わりました、田中です。", "はい", HANDOVER)
        self.assertFalse(f.holding)                                       # 次の相手の発話で解く
        # 代わった方：答えとして受け取らず、会話AIの報告によらず名乗りを流し直す（名乗りの流し直しの「代わった方へ」と同じ1か所＝Flow._not_an_answer。名乗りの録音の
        # 無い通話は、会話AIが短く名乗って用件を伝える＝_new_person_unrecorded）。⛔ 4e94ba37 まで、会話AIに「代わった方へ」を呼ぶよう差し戻し、呼ばなければ何も流れ
        # なかった（rv92/H）
        self.assertEqual((r["result"], f.items["Q1"].state), ("replayed", "empty"))
        self.assertIn("代わった方には、まだ名乗っていません", r["message"])
        r = self.report(f, "Q1", "はい、予約しています。", "はい", "はい")
        self.assertEqual(f.items["Q1"].state, "accepted")
        # 目的のお客様のいない業務で、保留のまま待ちきった：締めた理由は「保留で待ちきった」（繋がらなかった理由は持たない＝目的のお客様がいない）
        g = self.flow()
        self.report(g, "Q1", "少々お待ちください。", "はい", HOLD)
        r = g.on_hold_timeout()
        self.assertEqual((r["result"], g.end_reason, g.not_reached), ("end", "hold_timeout", None))

    def test_handover_replay_waits_for_the_new_person(self):
        # ⛔ G-50：代わった方への名乗りを、相手の「少々お待ちください」の直後に流していた ⇒ 判定が「取り次ぎを待つ」の間は流さない
        from flowctl import Flow, HANDOVER, HOLD, Question
        f = Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"), meanings=self.M)],
                 opening={"greeting": "お世話になっております。", "intro": "青葉物産の佐藤です。", "purpose": "ご予約の確認です。"})
        f.on_callee(); f.on_heard("少々お待ちください。"); f.on_check("judge", HOLD)
        r = f.apply("replay_opening", {"part": "handover"})
        self.assertEqual((r["result"], f.replays), ("hold", 0))
        f.on_callee(); f.on_heard("お電話代わりました。"); f.on_check("judge", HANDOVER)
        r = f.apply("replay_opening", {"part": "handover"})
        self.assertEqual((r["result"], f.replays), ("replayed", 1))

    def test_system_answer_with_an_ear_clash_is_asked_again(self):
        # 「わからない」も、聞き取りが食い違えば、そのまま受け取らずに聞き直す（言い直す選択肢が無いので、質問から）
        f = self.flow()
        f.on_callee(); f.on_heard("わからないです。"); f.on_check("ear", "わかりました")
        r = f.apply("record_answer", {"question_id": "Q1", "condition_id": "unknown"})
        self.assertEqual((r["result"], f.items["Q1"].state), ("ask_back", "unclear"))

    def test_each_utterance_starts_without_a_judgment(self):
        f = self.flow()
        f.on_check("judge", "はい")
        f.on_callee()
        self.assertIsNone(f.meaning_said)


class MeaningJudgeOptionsTest(unittest.TestCase):
    """意味の判定に見せる選べるもの（meaning_judge.options）：選択肢は意味の言葉を名前にする。⛔ G-53 の2回目：名前の「いいえ」と相手の
    「違います」を言葉で結びつけ、言い直しを認めていないのに認めたと読んだ（2回）。"""

    def test_g53_sets_are_read_by_group_name(self):
        # ⛔ 2026-11-15（伺い19 ア の小さな試しの前に見つけた）：--sets を文字の含まれ方で選んでいた（it["set"] in "N1N2…HEAR"）＝組 HEAR を選ぶと
        #    1文字の組 A・E も選ばれ、小さな試しのつもりで答えの段の全部の行へ送るところだった ⇒ 組の名前を1か所（g53_meaning.chosen_sets）で読み分ける
        import g53_meaning as g
        names = {"A", "B", "C", "D", "E", "F", "N1", "N2", "N3", "W1", "R", "HEAR"}
        self.assertEqual(g.chosen_sets("N1,N2,N3,W1,R,D,HEAR", names), ("N1", "N2", "N3", "W1", "R", "D", "HEAR"))
        self.assertEqual(g.chosen_sets("HEAR", names), ("HEAR",))   # A・E を選ばない
        self.assertEqual(g.chosen_sets("DABE", names), ("D", "A", "B", "E"))   # 前からの書き方（1文字の組の並び＝judge_try も使う）
        self.assertIsNone(g.chosen_sets(None, names))
        with self.assertRaises(SystemExit):   # 当たる組の無い名前は止める（黙って0行にしない）
            g.chosen_sets("N1,X9", names)

    def test_choices_are_named_by_meaning(self):
        import json
        from flowctl import ANY, HOLD, Question
        from meaning_judge import options, prompt, read
        q = Question("Q1", "ご予約の日時に変更はございませんでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                     meanings={"はい": "ご予約の日時に変更はないということ", "いいえ": "ご予約の日時に変更がおありということ"})
        names = [n for n, _, _ in options(q)]
        self.assertEqual(names[:2], ["ご予約の日時に変更はないということ", "ご予約の日時に変更がおありということ"])
        self.assertNotIn("- はい：", prompt(q, "違います。", "念のためご予約の日時に変更がおありということでよろしいでしょうか？"))
        self.assertEqual(read(q, json.dumps({"choice": "ご予約の日時に変更はないということ"})), "はい")
        self.assertEqual(read(q, json.dumps({"choice": HOLD})), HOLD)
        c = Question("Q2", "お支払いはどちらになさいますか？", "choice", conditions=("カード", "振込"), meanings={"カード": "わからない"})
        self.assertEqual([n for n, _, _ in options(c)][:3], ["カード", "振込", "どちらでも"])  # ほかの名前とかぶる意味の言葉は使わない
        self.assertEqual(read(c, json.dumps({"choice": "どちらでも"})), ANY)
        v = Question("Q3", "ご希望の日時をお聞かせいただけますでしょうか？", "datetime", conditions=("答えた",))
        self.assertEqual(read(v, json.dumps({"choice": "合っている"}), "念のため16日でよろしいでしょうか？"), "affirmed")
        self.assertIsNone(read(v, json.dumps({"choice": "はい"}), "念のため16日でよろしいでしょうか？"))

    def test_our_meaning_names_are_shown_as_names(self):
        # こちらが決めた意味の名前の質問（Question.named＝目的のお客様か・確かめへの返事・尋ねているか・待たせた方が戻ったか）は、意味の名前
        # （「ご本人」「別の方」「不在」など）を名前にし、意味の定義は説明に1回だけ（⛔ 2026-10-29：定義の長い文を名前にしていて、返事の形の指定に
        # 長い文が並び、「ご本人」と答えるたびに長い文を書き出していた／名前を「答えA」…にした形は、3.5 Flash Lite が取り次ぎのあとの
        # 「お電話代わりました。」を3回とも「代わった人が話し始めた」と読み、要らない確かめになった）。お客様の選択肢の言葉の質問は、前のまま（上の試験）
        import json
        from flowctl import ASKS_MEANINGS, ASKS_NO, Flow, Question, label
        from meaning_judge import _schema, jev_criteria, options, prompt, prompt_parts, read
        f = self.target_flow()
        for q in (*f.asks_questions.values(), f.return_question):
            self.assertTrue(q.named and not q.facets, q.id)
            names = [n for n, _, _ in options(q)][:len(q.conditions)]
            self.assertEqual(names, [label(c) for c in q.conditions])
            self.assertLess(len(json.dumps(_schema(q, None), ensure_ascii=False)), 400)   # 名前の決まりに長い定義を並べない
        q = f.asks_questions["T1"]
        said = prompt(q, "どちら様でしょうか？")
        self.assertIn(f"- {ASKS_NO}：{ASKS_MEANINGS[ASKS_NO]}", said)
        self.assertEqual(said.count(ASKS_MEANINGS[ASKS_NO]), 1)
        self.assertEqual(read(q, json.dumps({"choice": ASKS_NO})), ASKS_NO)
        self.assertIn(ASKS_MEANINGS[ASKS_NO], jev_criteria(q)[ASKS_NO])
        # まとめて送る区切りは、毎回同じ「決まり＋質問」の後ろ（つなげると1文字も違わない）
        head, rest = prompt_parts(q, "どちら様でしょうか？", None, "少々お待ちください。")
        self.assertEqual(head + rest, prompt(q, "どちら様でしょうか？", None, "少々お待ちください。"))
        self.assertEqual(head, prompt_parts(q, "別の言葉", None, None)[0])
        self.assertIn(ASKS_MEANINGS[ASKS_NO], head)   # 意味の定義（長くて毎回同じ）も前の部分＝まとめて送る

    @staticmethod
    def target_flow():
        from flowctl import Flow, Question
        return Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"))],
                    target={"target": "営業部部長の「岡田」様はいらっしゃいますでしょうか？", "target_confirm": "「おかだ」様でいらっしゃいますでしょうか？",
                            "mobile_confirm": "「おかだ」様で大丈夫でしょうか？"})   # 確かめる一言は2つ（CONFIRM_PARTS。⛔ 2026-11-20 まで target_reconfirm）

    def test_target_judgment_answers_each_fact_separately(self):
        # 目的のお客様の判定は、1つの言葉に同時に入りうる別々の事実を、項目ごとに1つずつ答える（✅ 2026-10-29 ユーザー：「『不在』と『別の方』と
        # いうのは、そもそも別の評価軸でしょ。それをどちらかしか選べないというのは設計上の問題じゃないですか？両方並立は相手の発言次第では当然
        # あり得るじゃないですか！」。⛔ 1つだけ選ぶ形では「いいえ、山田と申します。岡田は本日おりません。」を2つの判定がそろって「別の方」と読み、
        # 説明の言葉で順番を付けると「岡田ですね。」を「ご本人」と読んだ＝G-59 の 10-29）
        import json
        from flowctl import (ABOUT, ABOUT_DEPARTED, ABOUT_NONE, ABOUT_WRONG, HANDOVER, HOLD, PHONE, PHONE_NONE, SPEAKER, SPEAKER_NEW, SPEAKER_SAME, TARGET_IS_AWAY,
                             TARGET_IS_NOT, TARGET_IS_THERE, UNDECIDED, WHO, WHO_RECEPTION, facet_terms, says_away, says_busy, says_new, says_successor,
                             target_facets, target_reading)
        from meaning_judge import OTHER_JUDGES, _schema, facet_rules, jev_request, other_text, prompt, prompt_parts, read
        f = self.target_flow()
        self.assertEqual(f.calling_question.facets, target_facets(False, False))
        self.assertEqual([q.facets for q in f.confirm_questions.values()], [target_facets(True, False)] * 2)
        # 言葉の決まりも場面ごと（確かめる一言への返事の場面だけ、確かめる問いより前の言葉は、その問いへの答えではないと書く）
        self.assertEqual(f.calling_question.terms, facet_terms(False, False))
        self.assertEqual([q.terms for q in f.confirm_questions.values()], [facet_terms(True, False)] * 2)
        self.assertNotIn("確かめる問い", "".join(facet_terms(False, False)))
        self.assertIn("確かめる問いを言う前の言葉は、その問いへの答えではない", "".join(facet_terms(True, False)))
        # 説明の文は、前の言葉の見出しを名指しして結んでよい（「前に話した方」＝その前に相手が言ったことの最後の言葉を話した方）：項目ごとに答える質問には、
        # 前の言葉の行が必ずある（無いときは「無し」＝NO_BEFORE。⛔ 前は行が無いことがあったので、見出しを説明に混ぜないようにしていた）
        from meaning_judge import BEFORE, NO_BEFORE
        self.assertIn("その前に相手が言ったこと", "".join([*(d for fc in f.calling_question.facets for d in fc.choices.values()),
                                                       *(n for fc in f.calling_question.facets for n in fc.notes)]))
        for fq in [f.calling_question, *f.confirm_questions.values()]:
            self.assertIn(f"{BEFORE}：{NO_BEFORE}\n", prompt(fq, "はい。"))
        # 組み合わせ（唯一の決まり）：取り次ぎ ＞ 不在（ご本人ではない方） ＞ 電話に出ている方。読みに出ない事実は印で残す
        N, A = PHONE_NONE, ABOUT_NONE
        self.assertEqual(target_reading(TARGET_IS_NOT, N, TARGET_IS_AWAY), (TARGET_IS_AWAY, True, False))      # 別の方＋不在＝不在
        self.assertEqual(target_reading(UNDECIDED, HOLD, TARGET_IS_AWAY), (HOLD, True, False))                # 取り次ぎ＋不在＝待つ（不在は印）
        self.assertEqual(target_reading(TARGET_IS_NOT, HANDOVER, TARGET_IS_AWAY), (TARGET_IS_AWAY, True, True))  # 代わった方＋不在
        self.assertEqual(target_reading(TARGET_IS_NOT, HANDOVER, A), (HANDOVER, False, True))                 # 代わった違う方
        self.assertEqual(target_reading(TARGET_IS_THERE, HANDOVER, A), (TARGET_IS_THERE, False, True))         # 代わったご本人
        self.assertEqual(target_reading(TARGET_IS_THERE, N, TARGET_IS_AWAY), (TARGET_IS_THERE, True, False))   # ご本人がいまは話せない
        self.assertEqual(target_reading(TARGET_IS_NOT, N, A), (TARGET_IS_NOT, False, False))
        sp, _, ph, ab = target_facets()[:4]
        self.assertEqual(set(sp.choices), {SPEAKER_SAME, SPEAKER_NEW})   # 第1層はユーザーの形のとおり2つ（10-30）
        self.assertEqual(set(ph.choices), {N, HOLD})       # 電話を代わった方が話し始めたことは、前と同じ方かの物差し（10-30）
        from flowctl import ABOUT_NO_SUCH
        # 番号違いは分身 Z の (3)＝HolesZTest・会社の電話の「そういう方はいない」は伺い69 エ＝分身 M の NoSuchPersonRecallTest
        self.assertEqual(set(ab.choices), {A, TARGET_IS_AWAY, ABOUT_DEPARTED, ABOUT_NO_SUCH, ABOUT_WRONG})
        # 返事の読み方：項目ごとの名前 ⇒ 組み合わせた読みと印（flowctl.facts_reading）。どれか1つでも無い・選べるものに無ければ、読めない返事
        q = f.confirm_questions["target_confirm"]
        S = {SPEAKER: SPEAKER_SAME}
        r = read(q, json.dumps(S | {WHO: WHO_RECEPTION, PHONE: N, ABOUT: TARGET_IS_AWAY}))
        self.assertEqual((r, r.away, r.new, r.facts), (TARGET_IS_AWAY, True, False, S | {WHO: WHO_RECEPTION, PHONE: N, ABOUT: TARGET_IS_AWAY}))
        self.assertTrue(says_away(r) and not says_busy(r) and not says_new(r) and not says_successor(r))
        self.assertEqual(read(q, json.dumps(S | {WHO: WHO_RECEPTION, PHONE: N, ABOUT: ABOUT_DEPARTED})), TARGET_IS_AWAY)   # 在籍していないも不在の読み
        busy = read(q, json.dumps(S | {WHO: TARGET_IS_THERE, PHONE: N, ABOUT: TARGET_IS_AWAY}))
        self.assertTrue(busy == TARGET_IS_THERE and says_busy(busy) and not says_away(busy))
        new = read(f.calling_question, json.dumps({SPEAKER: SPEAKER_NEW, WHO: WHO_RECEPTION, PHONE: N, ABOUT: TARGET_IS_AWAY}))
        self.assertTrue(new == TARGET_IS_AWAY and says_new(new))
        self.assertEqual(read(f.calling_question, json.dumps({SPEAKER: SPEAKER_NEW, WHO: UNDECIDED, PHONE: N, ABOUT: A})), UNDECIDED)
        self.assertIsNone(read(q, json.dumps(S | {WHO: WHO_RECEPTION, PHONE: N})))
        self.assertIsNone(read(q, json.dumps({WHO: WHO_RECEPTION, PHONE: N, ABOUT: A})))       # 前と同じ方かの答えが無い
        self.assertIsNone(r.end)   # 電話を終える言葉かが無い返事（項目を足す前の記録）は、読んでいない＝None
        self.assertIsNone(read(q, json.dumps({SPEAKER: UNDECIDED, WHO: WHO_RECEPTION, PHONE: N, ABOUT: A})))
        self.assertIsNone(read(q, json.dumps(S | {WHO: "不在", PHONE: N, ABOUT: A})))
        self.assertIsNone(read(q, json.dumps(S | {WHO: TARGET_IS_NOT, PHONE: N, ABOUT: A})))  # 「別の方」は読みの名前で、選べるものではない
        self.assertIsNone(read(q, json.dumps({"choice": TARGET_IS_NOT})))
        # 問い合わせの文：項目ごとの決まり・質問・項目と選べるもの（毎回同じ＝まとめて送る前の部分）・その前の言葉・お客様の言葉
        head, rest = prompt_parts(q, "いいえ、山田と申します。", None, "少々お待ちください。")
        self.assertTrue(head.startswith(facet_rules(q)))
        for t in q.terms:
            self.assertEqual(head.count(f"- {t}\n"), 1)        # 言葉の決まりは1回だけ
        self.assertEqual(head + rest, prompt(q, "いいえ、山田と申します。", None, "少々お待ちください。"))
        self.assertEqual(head, prompt_parts(q, "別の言葉", None, None)[0])
        for fc in q.facets:
            self.assertIn(f"{fc.heading}（{fc.key}）", head)
            for n, d in fc.choices.items():
                self.assertEqual(head.count(f"- {n}：{d}"), 1)
            for note in fc.notes:
                self.assertEqual(head.count(f"・{note}\n"), 1)   # 見分け方も1回だけ
        self.assertEqual(_schema(q, None)["required"], [SPEAKER, WHO, PHONE, ABOUT, "end", "hear", "offer", "absent_why"])   # 電話を終える言葉か（11-01）・届いていない様子か（11-02）・相手の申し出と出られない理由（rv92/H）
        self.assertEqual(_schema(q, None)["properties"][ABOUT]["enum"], list(ab.choices))
        # Jev：項目ごとに1つの問い（言い切っているかは問わない）。確かめの線は、項目のうち一番低い確からしさで当てる
        jq = jev_request("m", q, "いいえ、山田と申します。")["questions"]
        self.assertEqual((list(jq), jq[ABOUT]["criteria"]), ([SPEAKER, WHO, PHONE, ABOUT, "end", "hear", "offer", "absent_why"], ab.choices))   # 答えとは別に読む項目（11-01・11-02・rv92/H）
        # Jev にも、見分け方と言葉の決まりを、判定の文と同じ1か所から渡す（言葉の決まりは、その言葉を説明に使う項目だけ）
        who_q = q.facets[1]
        self.assertTrue(all(n in jq[WHO]["instructions"] for n in who_q.notes) and all(t in jq[WHO]["instructions"] for t in q.terms))
        self.assertNotIn("言葉の決まり", jq[PHONE]["instructions"])
        got = json.loads(other_text("Jev 1.14", {"answers": {SPEAKER: {"choice": SPEAKER_SAME, "confidence": 0.9}, WHO: {"choice": WHO_RECEPTION, "confidence": 0.99},
                                                             PHONE: {"choice": N, "confidence": 0.98}, ABOUT: {"choice": TARGET_IS_AWAY, "confidence": 0.7}}}))
        self.assertEqual((got[WHO], got[ABOUT], got["sure"]), (WHO_RECEPTION, TARGET_IS_AWAY, 0.7))
        self.assertEqual(read(q, json.dumps(got)).sure, 0.7)
        # 1つだけ選ぶ質問の Jev の返事の読み方は前のまま。言い切っているかのもとの確からしさ（firm_p）も添えて、読みに残す（線と、どちらとも
        # 言えない幅を決める測りが使う＝2026-10-31）
        one = json.loads(other_text("Jev 1.14", {"answers": {"choice": {"choice": "はい", "confidence": 0.9}, "firm": {"noul": 0.1}}}))
        # 会話になっているか（10-31 に足した FITS）は、同じ日の夜に外した（✅ ユーザー「(a) OK」）＝返事に入れない
        # 問いごとの確からしさ（confs）と選べるもの全部の確からしさ（probs。この返事には無い）は、測りの記録だけが使う（11-07 10時29分25秒）
        self.assertEqual(one, {"choice": "はい", "firm": 0.1 >= OTHER_JUDGES["Jev 1.14"]["firm_min"], "sure": 0.9, "firm_p": 0.1,
                               "probs": None, "confs": {"choice": 0.9}})
        from flowctl import Question
        yn = Question("q", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"))
        self.assertEqual((read(yn, json.dumps(one)).firm_p, read(yn, json.dumps({"choice": "はい", "firm": True})).firm_p), (0.1, None))
        self.assertIsNone(other_text("Jev 1.14", {"answers": {WHO: {"choice": None, "confidence": 0.9}}}))

    def test_g59_facts_agree_with_the_readings_it_accepts(self):
        # G-59 の事実ごとの正解（項目ごと）と、受け取ってよい読み（流れの制御の読み）が食い違わない：事実ごとの正解の組み合わせを、流れの制御の
        # 1か所（target_reading）で読みにすると、どれも受け取ってよい読みに入る。2つの事実が重なる言葉は、事実が2つ以上ある
        import g59_calling_judge as g
        from flowctl import ABOUT, ABOUT_NONE, PHONE, PHONE_NONE, WHO, target_facets
        cases = g.cases("「おかだ」様でいらっしゃいますでしょうか？")
        self.assertEqual(len(cases), len({(t, b, bool(a), succ) for t, _, b, a, succ, _ in cases}))   # 同じ場面の言葉を2回数えない
        for text, accept, before, asked, successor, facts in cases:
            self.assertLessEqual(set(g.accept_of(facts, successor)), set(accept), text)
            self.assertLessEqual(set(accept) - set(g.accept_of(facts, successor)), set(g.EXTRA.get((text, before), ())), text)   # 足した読みはご決定の分だけ
            # 正解の項目と中の名前は、その場面で判定に見せる項目と選べるものの中（Flow._calling_questions と同じ選び分け）
            shown = {fc.key: fc.choices for fc in target_facets(bool(asked), successor)}
            self.assertEqual(set(facts), set(shown), text)   # どの行も、判定に見せる項目のすべてに正解がある（相手の申し出・理由も＝2026-11-19 日本時間21時台）
            for k, got in facts.items():
                self.assertTrue(got and got <= set(shown[k]), (text, k))
        for text, before, confirmed, f in g.LINES_BOTH:
            self.assertGreaterEqual((f[PHONE] != {PHONE_NONE}) + (f[ABOUT] != {ABOUT_NONE}) + (f[WHO] != {"決められない"}), 2, text)

    def test_target_facets_say_each_condition_once(self):
        # 目的のお客様の判定の説明の文は、1つの条件を1か所だけに書く（⛔ 2026-10-30＝帳面 0-2 の21回目の失敗：同じ境目を両側の説明に書き、片方だけ
        # 直して食い違わせた・ほかの説明の条件を一部だけ写して行き過ぎた・同じ言葉の中身を何か所にも書いた）。場面の呼び方（flowctl.called_words）と
        # 言葉の決まりの名前は、決まった言葉なので数えない。説明の例は、試しの言葉（G-59）と同じ言い方にしない（測りが本番の力を表さなくなる）
        import re
        from types import SimpleNamespace
        import g59_calling_judge as g
        from flowctl import (BEFORE, CHANGED, FIRST_ANSWERER, NAME_CHECK, OTHER_NAME, OTHER_PERSON, RELAY_WORDS, called_words, facet_terms,
                             target_facets)
        from meaning_judge import facet_rules
        N = 14
        tests = {t for t, *_ in g.cases("x")} | {b for _, _, b, *_ in g.cases("x") if b}
        for asked in (False, True):
            for seeks in (False, True):
                P, NOT_P = called_words(seeks)
                items = [(f"{fc.key}:{n}", d) for fc in target_facets(asked, seeks) for n, d in fc.choices.items()]
                items += [(f"{fc.key}:見分け方{i}", t) for fc in target_facets(asked, seeks) for i, t in enumerate(fc.notes)]
                items += [(f"言葉{i}", t) for i, t in enumerate(facet_terms(asked, seeks))]
                rules = facet_rules(SimpleNamespace(seeks_successor=seeks, terms=facet_terms(asked, seeks))).split("決まり：\n", 1)[1]   # 言葉の決まりの行は「言葉」で数えた
                items += [(f"決まり{i}", l) for i, l in enumerate(rules.split("\n")) if l.startswith("- ")]
                seen = {}
                for name, text in items:
                    for w in (NOT_P, P, CHANGED, OTHER_PERSON, NAME_CHECK, RELAY_WORDS, FIRST_ANSWERER, OTHER_NAME, BEFORE):
                        text = text.replace(w, "＊")
                    for i in range(len(text) - N + 1):
                        if "＊" not in text[i:i + N]:
                            seen.setdefault(text[i:i + N], set()).add(name)
                shared = {k: sorted(v) for k, v in seen.items() if len(v) > 1}
                self.assertEqual(shared, {}, (asked, seeks))
                for name, text in items:
                    for ex in re.findall(r"「([^「」]+)」", text):
                        for who in ("岡田", "田中", "山本", "山田"):
                            ex2 = ex.replace("〇〇", who)
                            if len(ex2) >= 11:
                                self.assertFalse(any(ex2 in t for t in tests), (name, ex2))

    def test_target_facets_keep_every_boundary(self):
        # 話している方は誰かの、隣り合う答えの境目は、どの場面でも見分け方に1つずつある（⛔ 2026-10-30：境目を1か所に寄せて作り直したときに、受付の方と
        # 決められないの境目を落とし、Luna は「岡田ですね。」を決められない・「どういったご用件でしょうか？」を受付の方と読んだ）。言葉の決まりの
        # 名前は、その中身を言い表す（⛔ 同じ日：「ほかの人として話した」に「名前をくり返して確かめた」を入れ、Luna は名前の確かめを当てなかった）
        from flowctl import NAME_CHECK, OTHER_NAME, RELAY_WORDS, UNDECIDED, WHO, WHO_RECEPTION, facet_terms, target_facets
        for asked in (False, True):
            for seeks in (False, True):
                notes = next(fc for fc in target_facets(asked, seeks) if fc.key == WHO).notes
                for other in ("別の方", "代理の方", UNDECIDED):
                    self.assertEqual(sum(n.startswith(f"{WHO_RECEPTION}と{other}：") for n in notes), 1, (asked, seeks, other))
                self.assertEqual(sum(n.startswith(f"取り次がれて") and RELAY_WORDS in n for n in notes), 1)   # 取り次がれて出た方の決め方
                self.assertEqual(sum(n.startswith(f"{OTHER_NAME}を名乗った方は") for n in notes), 1)          # お名前の違う方
                terms = facet_terms(asked, seeks)
                self.assertTrue(all("名前" not in t.split("＝", 1)[1] for t in terms if t.startswith("「ほかの人として話した」")))
                self.assertTrue(any(t.startswith(f"{NAME_CHECK}＝") and "名前をくり返して確かめた" in t for t in terms))

    def test_successor_words_only_in_the_successor_scene(self):
        # 後任の方の場面だけの言葉は、その場面の問い合わせにだけ入る（⛔ 2026-10-30 G-59：後任の方の場面のために「在籍していない」に足した一文を、
        # 考えない Sonnet が、ふつうの場面の「いえ、岡田は退職しまして、私が後任の田中です。」にも当てた）
        f, b = TargetTest().flow()
        from meaning_judge import prompt_parts
        heads = {asked: prompt_parts(f.for_judge(q), "はい。", None, None)[0] for asked, q in ((False, f.calling_question), (True, f.confirm_questions["target_confirm"]))}
        f._to_successor()
        succ = {asked: prompt_parts(f.for_judge(q), "はい。", None, None)[0] for asked, q in ((False, f.calling_question), (True, f.confirm_questions["target_confirm"]))}
        for word in ("いまお呼びしている方", "前任の方", "後任の方はいない", "後任のご担当者様をお呼び", "後任のご担当者様かを確かめた"):
            for asked in (False, True):
                self.assertNotIn(word, heads[asked], (word, asked))
        for asked in (False, True):
            self.assertIn("いまお呼びしている方", succ[asked])
            self.assertIn("後任の方はいない", succ[asked])
        self.assertIn("後任のご担当者様かを確かめた", succ[True])

    def test_g59_tally_counts_the_end_reading_as_a_flow_change(self):
        # お呼びする段でも、判定の「電話を終える言葉か」の読みは、流れの制御の動きを変える（Flow._end_due_now：読めば会話AIの報告が無くても
        # 締める・急いでいる方への伺い／「言っていない」なら続ける／決まらなければ _end_unsure）。数える1か所（g59_tally.flow_miss＝本番の流れの制御に通す）が、
        # この項目を数えに入れる（⛔ 2026-11-05 に見つけた：11-01 に項目を足したとき、答えの段の数え（いまの g53_meaning.flow_miss の中）には入れたが、
        # お呼びする段の数えには入れず、d1-ultra が「…いま会議中で手が離せないのですが。」を急いでいると読んだ外れを「項目だけ」と数えていた）
        import g59_tally as t
        from flowctl import (ABOUT, END, END_HURRY, END_NONE, END_REFUSED, PHONE, SPEAKER, SPEAKER_NEW, TARGET_IS_AWAY, TARGET_IS_THERE,
                             UNDECIDED, WHO)
        r = {"text": "はい、岡田です。申し訳ありません、いま会議中で手が離せないのですが。", "before": "岡田ですね。少々お待ちください。",
             "asked": None, "successor": False}
        facts = {SPEAKER: {SPEAKER_NEW}, WHO: {TARGET_IS_THERE}, PHONE: {"何もない"}, ABOUT: {TARGET_IS_AWAY}, END: {END_NONE}}
        right = {SPEAKER: SPEAKER_NEW, WHO: TARGET_IS_THERE, PHONE: "何もない", ABOUT: TARGET_IS_AWAY, END: END_NONE}
        self.assertIsNone(t.flow_miss(right, facts, r))
        self.assertEqual(t.flow_miss(right | {END: END_HURRY}, facts, r), t.ALL_REPORTS)        # 続けるべきところで、急いでいる方への伺い
        self.assertEqual(t.flow_miss(right | {END: UNDECIDED}, facts, r), t.ALL_REPORTS)        # 決まらないときの確かめ
        self.assertEqual(t.flow_miss(right, facts | {END: {END_REFUSED}}, r), t.ALL_REPORTS)   # 断られたのに締めない
        self.assertFalse(t.same_moves(right, right | {END: END_HURRY}, r))   # 判定どうしのそろい（agree）も同じ1か所
        # 電話を終える読み（決められないも）は、会話AIのどの報告より先に次の動きを決める（Flow._end_due_now）＝その発話の目的のお客様の読みが
        # 違っても、電話を終える読みが同じなら動きは同じ（「申し訳ございません、今ちょっとバタバタしておりまして。」を不在＋急いでいると読んだ行）
        hurry = facts | {ABOUT: {"言っていない"}, END: {END_HURRY}}
        self.assertIsNone(t.flow_miss(right | {END: END_HURRY}, hurry, r))
        self.assertIsNone(t.flow_miss(right | {WHO: UNDECIDED, END: END_HURRY}, hurry, r))
        self.assertEqual(t.flow_miss(right | {END: END_REFUSED}, hurry, r), t.ALL_REPORTS)        # 違う理由で締める
        self.assertEqual(t.flow_miss(right | {END: UNDECIDED}, hurry, r), t.ALL_REPORTS)
        # 項目を足す前の記録（読みに END が無い）は、この項目を数えない（g59_calling_judge.facts_ok と同じ決まり）
        old = {k: v for k, v in right.items() if k != END}
        self.assertIsNone(t.flow_miss(old, facts | {END: {END_REFUSED}}, r))

    def test_g59_unsure_reading_is_taken_in_the_priority_order(self):
        # ⛔ 2026-11-06 日本時間23時22分41秒のご質問の見直し（判定の組と測りの持ち場 J2）：お呼びする段の測り（g59_calling_judge の fill）は、答えが無かった行の
        #    確かでない読みを、届いた順の最初で取っていた（本番は優先の順＝unsure_order・NoJudgment.unsure。15時台に本番だけ直した写し漏れ）
        import g59_calling_judge as g
        from meaning_judge import NoJudgment, RACE, members_for, unsure_order
        order = members_for(RACE, "asks")
        late, first = order[0], order[1]   # 優先の順の先（d1-ultra）が、届いたのは後
        tried = [{"model": first, "unsure": "尋ねていない"}, {"model": late, "unsure": "尋ねている"}]
        exc = NoJudgment(tried, unsure_order(tried, order))
        self.assertEqual(g.unsure_of(False, exc), g.unsure_of(False, NoJudgment([tried[1]], [tried[1]])))

    def test_why_answers_are_not_the_label_notes(self):
        # ⛔ 2026-11-06 日本時間23時22分41秒のご質問の見直し（判定の組と測りの持ち場 J1）：わからない・答えたくない理由の正解を、正解の表の why（正解を付けた
        #    理由のメモの文。782行すべてにある）から読んでいた＝理由の読み「決められない」は、メモの文にその字を含む行で「正しい」になった（選べるものに無い名前も）
        # ⇒ 理由の正解は別の鍵（reason）。選べる理由の名前（flowctl.why_choices）だけを数える
        from flowctl import why_choices
        from g53_meaning import why_accept
        names = list(why_choices(False))
        memo = {"set": "C", "qid": "G1", "text": "x", "label": {"accept": ["unknown"], "why": "どちらとも言っていない＝決められない"}}
        self.assertIsNone(why_accept(memo))
        row = {**memo, "label": {**memo["label"], "reason": [names[0], "もう一方"]}}
        self.assertEqual(why_accept(row), [names[0]])

    def test_g59_tally_waits_like_the_running_call(self):
        # ⛔ 2026-11-06 日本時間13時台の見直し（判定の組の持ち場の A4）：本番の会話の側は、判定を待つ間に新しい方へのあいさつの録音（Flow.hold_play）を流すと、
        #    その長さだけ待つ長さを延ばす（✅ 2026-10-22 ユーザー：「…その間に判定を待てばいいんじゃないですか？」）が、測りの数え（g59_tally.outcomes）は
        #    2秒（Limits.hold_s）だけで組を動かしていた＝d1-ultra が2秒を過ぎてあいさつの間に届く行を、Jev で決めたと数えうる
        # ⇒ 待つ長さは1か所（Limits.judge_wait_s）。あいさつを流す回かは会話AIの報告と電話口の方で決まり、測りは持たないので、両方の待つ長さで動かす
        import convo
        import g59_tally
        from flowctl import Limits
        from instruction import VOICE_TYPES
        held = {round(convo.recording_seconds(v, "greeting"), 3) for v in VOICE_TYPES}
        self.assertEqual(Limits().judge_wait_s(), Limits.hold_s)
        self.assertEqual({round(Limits().judge_wait_s(h) - Limits.hold_s, 3) for h in held}, held)
        # あいさつを流しうるのは、まだあいさつを聞いていないかもしれない新しい方（取り次ぎの言葉のあとの方）の行だけ（名乗りの頭であいさつを聞いた方・
        # 確かめる一言への返事は延ばさない＝本番の Flow.hold_play）
        self.assertEqual(set(g59_tally.waits(True)), {Limits.hold_s} | {Limits().judge_wait_s(h) for h in held})
        self.assertEqual(g59_tally.waits(False), (Limits.hold_s,))
        self.assertEqual([g59_tally.new_person({"before": b, "asked": a}) for b, a in (("", None), ("少々お待ちください。", None), ("少々お待ちください。", True))],
                         [False, True, False])
        # d1-ultra の確かな読みが 2.5秒（2秒より遅く、あいさつの間には間に合う）・Jev の確かな読みが 0.5秒：新しい方の行は、あいさつを流さない回は Jev、
        # 流す回は d1-ultra（どちらにもなる）・あいさつを聞いた方の行は Jev だけ
        runs = [(2.5, True, "d1"), (0.5, True, "jev")]
        self.assertEqual({w for w, *_ in g59_tally.outcomes(runs, (0, 1), new=True)}, {0, 1})
        self.assertEqual({w for w, *_ in g59_tally.outcomes(runs, (0, 1))}, {1})
        # どちらの回でも決まる判定が同じ行は、今までどおり1つ（d1-ultra が2秒の前に届く）
        self.assertEqual({w for w, *_ in g59_tally.outcomes([(1.0, True, "d1"), (0.5, True, "jev")], (0, 1), new=True)}, {0})

    def test_cost_tool_holds_no_group_of_its_own(self):
        # ⛔ 2026-11-06 日本時間23時22分41秒のご質問の見直し（判定の組の持ち場の J6）：料金の道具（judge_cost）は、組の決め方と確かな読みの決まりを手で
        # 写していた。⛔ 2026-11-18 日本時間15時台（見直し (13) の持ち場 D の D13）：決め方を本番の1か所にしたあとも、組の顔ぶれ（Jev を先頭に考えない Sonnet）と
        # 先に出すもの（並びの最初）を手で書いていた＝本番は members_for（答えの段は d1-ultra・Jev・考える Sonnet）・leads_of（d1-ultra と Jev）。
        # 記録（10-25 の G-53race・10-24 の G-63G67each）に d1-ultra の読みが無く、本番の組では数えられない ⇒ 送り方の比べは外した。本番の組で決める数えは、
        # お呼びする段が g59_tally.cascade（記録の無い判定で決まりうる行は数えない）・答えの段は G-53 の組の測り（本番の JudgePanel で送る＝g53_meaning.run_group）
        import judge_cost as jc
        for name in ("decide", "compare_meaning", "compare_grounding", "WAITS", "J"):
            self.assertFalse(hasattr(jc, name), name)
        self.assertTrue(callable(jc.paid_calls))   # 送った回数の数え（組を持たない）は残す

    def test_g59_tally_cascade_decides_with_the_production_race(self):
        # 測りの数え（g59_tally.cascade）は、どの判定で決めるかを本番の組の1か所で決める：顔ぶれ（members_for）・確かな読み（sure_reading）・
        # 先に出すもの（leads_of）・決め方（Race）。判定ごとの記録（1つの判定で測った結果）の秒で、本番と同じに決め、記録の無い判定（測っていない
        # Sonnet・まだ流していない Jev）で決まりうる行は、その判定の名前を添えて分けて数える（記録の無い判定の読みを推し量らない）。
        # ⛔ 2026-11-06 日本時間8時台（EN-C の指摘8）：線を手で渡し、並べた順で線から上かだけを見ていた（届いた秒を見ない）
        import json
        import tempfile
        from pathlib import Path
        from unittest import mock

        import g59_calling_judge as g
        import g59_tally as t
        text, _, before, asked, succ, facts = next(c for c in g.cases("確かめる一言") if not c[2] and c[3] is None and not c[4])
        right = {k: sorted(v)[0] for k, v in facts.items()}
        D1, JEV = "d1 Ultra（Liquid）", "Jev 1.14"

        def row(name, s, sure):
            r = {"text": text, "before": before, "asked": asked, "successor": succ, "rep": 0, "asks_accept": None, "judge2_s": s}
            if sure is None:   # 確かでない読み（測りの道具は答えに残さない）
                return r | {"judge2_tried": [{"model": name, "unsure": "決められない", "sure": 0.3, "s": s}]}
            return r | {"judge2_by": name, "judge2_sure": sure, "judge2_facts": right}

        def count(*files):
            with tempfile.TemporaryDirectory() as d:
                names = []
                for i, rows in enumerate(files):
                    (Path(d) / f"{i}.json").write_text(json.dumps({"rows": rows}, ensure_ascii=False), encoding="utf-8")
                    names.append(f"{i}.json")
                with mock.patch.object(t, "RESULTS", Path(d)):
                    return t.cascade(names)
        part = "目的のお客様の判定"
        got = count([row(D1, 2.5, 0.99)], [row(JEV, 0.1, 0.99)])
        self.assertEqual(dict(got["決めた判定"]), {(part, JEV): 1})       # d1-ultra は待つ長さに間に合わない＝Jev（指摘8の行）
        self.assertEqual(dict(got["動きが変わる外れ"]), {})
        self.assertEqual(dict(count([row(D1, 1.5, 0.99)], [row(JEV, 0.1, 0.99)])["決めた判定"]), {(part, D1): 1})
        self.assertEqual(dict(count([row(D1, 0.5, 0.99)])["決めた判定"]), {(part, D1): 1})   # Jev の記録が無くても d1-ultra で決まる
        late = count([row(D1, 2.5, 0.99)])                                    # Jev の記録が無いと決まらない
        self.assertEqual(dict(late["決めた判定"]), {})
        self.assertIn(JEV, late["記録が足りない"][0][-1])
        unsure = count([row(D1, 0.2, None)], [row(JEV, 0.1, None)])          # どちらも確かでない：測っていない Sonnet に回る
        self.assertEqual(dict(unsure["決めた判定"]), {})
        self.assertEqual(sum(unsure["記録の無い判定に回る"].values()), 1)
        self.assertIn("Claude Sonnet 5.5", next(iter(unsure["記録の無い判定に回る"]))[1])
        with self.assertRaises(SystemExit):                                   # 組の記録（2つ以上の判定）は、判定ごとの記録にならない
            count([row(D1, 0.5, 0.99), row(JEV, 0.1, 0.99) | {"rep": 1}])
        # 項目を足す前の記録（電話を終える言葉か・声が届いていない様子かが無い読み）は、足した項目を数えない（g59_calling_judge.facts_ok と同じ
        # 1か所＝facts_whole）。⛔ 2026-11-06 日本時間8時台に見つけた：数えは「項目の数が正解の表と同じか」を手で見ていて、10-31 の記録の Jev の読みを
        # 流れの制御の動きが同じなのに外れと数えた（確かめへの返事で13行）
        from flowctl import END, HEAR
        old_row = row(D1, 0.5, 0.99)
        old_row["judge2_facts"] = {k: v for k, v in right.items() if k not in (END, HEAR)}
        got = count([old_row])
        self.assertEqual((dict(got["決めた判定"]), dict(got["動きが変わる外れ"])), ({(part, D1): 1}, {}))
        self.assertTrue(g.facts_whole(old_row["judge2_facts"], facts))
        self.assertFalse(g.facts_whole({k: v for k, v in right.items() if k != "who"}, facts))   # 流れの制御が使う項目が無い読みは、そろっていない
        # 取り次ぎの言葉のあとの新しい方の行：本番は、繋ぐ報告なら判定を待つ間にあいさつを流して待つ長さを延ばす（Limits.judge_wait_s・Flow.hold_play）＝
        # 2秒より遅い d1-ultra でも決まりうる＝決めた判定に数えず「待つ長さで変わる」（どちらの読みも外れを数える）。⛔ 13時台の見直しの A4
        text, _, before, asked, succ, facts = next(c for c in g.cases("確かめる一言") if c[2] and c[3] is None and not c[4])
        right = {k: sorted(v)[0] for k, v in facts.items()}
        got = count([row(D1, 2.5, 0.99)], [row(JEV, 0.1, 0.99)])
        self.assertEqual((dict(got["決めた判定"]), len(got["待つ長さで変わる"])), ({}, 1))

    def test_g59_tally_never_misses_a_change_the_flow_check_finds(self):
        # 数える道具（g59_tally.flow_miss）は、会話の試し（g59_flow_check＝流れの制御そのもの）で動きが変わる外れを、「同じ」と数えない（✅ 2026-10-30
        # ユーザー：「流れの制御の動きが変わる外れの原因と理由が何かを…しっかりと分析した方がいいんじゃないですか？」⛔ 同じ日：会話の試しの道具の字を
        # 書き間違え、どれも「同じ」と出た＝道具は、答えが分かっている例で先に確かめる）。2026-11-18（見直し (13) の D1・D2）から、数える道具も本番の
        # 流れの制御に通す（報告ごとに比べる＝off_reports）＝会話の試しの形の報告で動きが変わるかが、会話の試しと同じ
        import g59_calling_judge as g
        import g59_flow_check as fc
        import g59_tally as t
        from flowctl import ASKS_NO
        right, wrong, succ = fc.CASES[0][1:]
        self.assertTrue(fc.changes(right, wrong, succ))        # 変わる例（名乗りを聞いていない岡田様に、名乗りを流さない）
        self.assertFalse(fc.changes(right, right, succ))       # 同じ読みなら同じ
        checked, asking = 0, 0
        for name, right, wrong, succ in fc.CASES:
            if right[:-1] != wrong[:-1]:
                continue   # 外れが前の言葉の読みにある形（行の数えは、行の言葉の読みを比べる＝前の言葉は正解の表の読み BEFORE_READ）
            facts = {k: {v} for k, v in fc.facts(right[-1][1]).items()}
            _, _, ctx = fc.run(wrong, succ)
            report = next(n for n, op in fc.REPORTS if op == wrong[-1][2])
            off = t.off_reports(fc.facts(wrong[-1][1]), facts, ctx | {"text": wrong[-1][0]})
            if g.asks_truths(wrong[-1][0]) != (ASKS_NO,):
                # こちらへの質問（「どちらの岡田でしょうか？」）：数えは、同時に出る尋ねているかの問い合わせを正しい読みで渡す（本番は質問に先に答える＝
                # Flow._asking_now）＝目的のお客様の判定の外れは、目的の人の報告では動きを変えない（会話の試し run は尋ねているかを渡さない形）
                self.assertNotIn(report, off, name)
                asking += 1
                continue
            self.assertEqual(report in off, fc.changes(right, wrong, succ), name)
            checked += 1
        self.assertEqual((checked, asking), (8, 2))


class UnreportedNoteTest(unittest.TestCase):
    """AIが声は出したのに、報告なしでターンを終えたときの、報告を促す知らせ（Flow.unreported_note）。
    ⛔ 2026-10-17：記録の通話で、「はい。」などのあとに報告が抜けた回が34回。プログラムは気づく手立てを持っていなかった。
    ⛔ 1回目は判定を見ずに出し、取り次ぎのあとの知らせで会話が乱れた ⇒ 意味の判定が「答え」と決めたときだけ。"""

    def flow(self):
        from flowctl import Flow, Question
        return Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                              meanings={"はい": "ご予約はお済みということ", "いいえ": "ご予約はまだということ"})])

    def test_only_for_an_answer_once_per_utterance(self):
        f = self.flow()
        f.on_callee(); f.on_heard("はい。"); f.on_check("judge", "はい")
        note = f.unreported_note()
        self.assertIn("「はい。」", note)
        self.assertIn("record_answer", note)
        self.assertNotIn("ご予約はされていますでしょうか", note)   # 質問の文は入れない（AIが自分で質問し直さないように）
        self.assertIsNone(f.unreported_note())                      # 同じ発話には1回まで
        f.on_callee(); f.on_heard("ちょっとわからないです。"); f.on_check("judge", "unknown")
        self.assertIsNotNone(f.unreported_note())                   # 「わからない」も答え

    def test_not_for_words_that_are_not_an_answer(self):
        from flowctl import HOLD, UNDECIDED
        f = self.flow()
        for kind in (HOLD, UNDECIDED):
            f.on_callee(); f.on_heard("担当の者に代わりますので少々お待ちください。"); f.on_check("judge", kind)
            self.assertIsNone(f.unreported_note())                  # 取り次ぎ・考えている途中
        f.on_callee(); f.on_heard("はい。")
        self.assertIsNone(f.unreported_note())                      # 判定が無い

    def test_not_after_the_end_or_while_confirming(self):
        f = self.flow()
        f.on_callee(); f.on_heard("大丈夫です。")
        f.apply("record_answer", {"question_id": "Q1", "condition_id": "はい", "value": "大丈夫です。"})
        self.assertEqual(f.awaiting_confirm, "Q1")
        f.on_callee(); f.on_heard("はい、そうです。"); f.on_check("judge", "はい")
        self.assertIsNone(f.unreported_note())                      # 言い直しへの返事を待っている（報告は confirm_field）
        f.apply("confirm_field", {"question_id": "Q1", "result": "affirmed"})
        f.on_callee(); f.on_heard("はい。"); f.on_check("judge", "はい")
        self.assertEqual(f.phase, "closing")
        self.assertIsNone(f.unreported_note())


class ChoicesNoteTest(unittest.TestCase):
    """会話のAIにも、選択肢の意味（取込で決めた意味の言葉）を知らせる（flowctl.choices_note の1か所）。⛔ 2026-10-17：選択肢の名前しか
    見せておらず、打ち消しの問いの「はい」の向きをAIが自分で決めていた。"""

    def test_note_on_every_question_announcement(self):
        from flowctl import Flow, Question, choices_note
        from instruction import Business, build
        q1 = Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"))
        q2 = Question("Q2", "ご不明な点はございませんでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                      meanings={"はい": "ご不明な点はないということ", "いいえ": "ご不明な点がおありということ"})
        self.assertEqual(choices_note(q1), "")                                  # 意味の言葉が無ければ足さない
        self.assertIn("「はい」＝ご不明な点はないということ", choices_note(q2))
        for play in (False, True):
            f = Flow([q1, q2], play_recordings=play)
            f.on_callee(); f.on_heard("はい、しています。")
            r = f.apply("record_answer", {"question_id": "Q1", "condition_id": "はい", "value": "はい、しています。"})
            self.assertIn("ご不明な点はないということ", r["message"])               # 次の質問の知らせ（録音で流す形も）
        b = Business(company="株式会社青葉物産", caller="佐藤", purpose="確認", questions=[q2, q1])
        for mode in ("ai", "recorded"):
            _, text = build(b, "S4", opening_mode=mode)
            self.assertIn("ご不明な点はないということ", text)                       # 最初の質問


class ResendTest(unittest.TestCase):
    def test_resend_keeps_the_count_and_clears_the_words(self):
        # 張り替えて同じ発話を送り直す（6-7）：相手は話していないので数えず、文字だけを受け取り直す（⛔ 前は同じ言葉が2回たまった）
        from flowctl import Flow, Question
        f = Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"))])
        f.on_callee(); f.on_heard("はい。"); f.on_check("ear", "はい"); f.on_check("judge", "はい")
        n = f.callee_turns
        f.on_resend(); f.on_heard("はい。")
        self.assertEqual((f.callee_turns, f.callee_said, f.ear_said, f.meaning_said), (n, "はい。", None, None))


class AmbiguousAnswerTest(unittest.TestCase):
    """DESIGN.md 6-10 の (3)：受け入れにも断りにも取れる答え（「大丈夫です」「結構です」）は、AIが選んだ選択肢のまま渡さず、意味を確かめる。
    ⛔ G-14：AIは24本中21本で、曖昧な答えを「はい」「いいえ」に決めた。⛔ 2026-10-17 に見つけた穴：選択肢の型の言い直しが
    「はいとおっしゃいましたでしょうか？」になり、言い直しを打ち消されても選択肢は「はい」のままだった（依頼主へ「はい」が渡る）。"""
    M = {"はい": "ご予約はお済みということ", "いいえ": "ご予約はまだということ"}

    def flow(self, meanings=None, required=True, play=False):
        from flowctl import Flow, Question
        return Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"), required=required,
                              meanings=self.M if meanings is None else meanings),
                     Question("Q2", "お支払いはカードと振込のどちらがよろしいでしょうか？", "choice", conditions=("カード", "振込"))],
                    play_recordings=play)

    @staticmethod
    def say(f, heard, op, **args):
        f.on_callee(); f.on_heard(heard)
        return f.apply(op, args)

    def test_list(self):
        # 曖昧な答えの決まりは、流れの制御の比べ（Flow._compare）の1か所で当てる
        from flowctl import Flow, Question
        q = Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"))

        def why(t, reported="はい", policy=True, confirming=False):
            return Flow._compare(q, t or "", "affirmed" if confirming else reported, {}, policy=policy, confirming=confirming)[0]
        from flowctl import HEDGE_WHY
        for t in ("大丈夫です。", "結構です", "いいです。", "あ、大丈夫です。", "えーと、結構です。", "大丈夫です、大丈夫です。", "いいですよ。"):
            self.assertEqual(why(t), "曖昧な答え", t)
        for t in ("家族がしたかもしれないです。", "たぶんカードです。", "多分してます", "おそらくまだです", "したかも。"):  # 言い切っていない答え
            self.assertEqual(why(t), HEDGE_WHY, t)
        # 認める・打ち消す言葉が付いていれば、その言葉で決まる。「いいえ」は打ち消し。文字が無ければ決めない。「と思います」は言い切りの柔らかい形
        for t in ("はい、大丈夫です。", "いいえ。", "いえ、結構です。", "どちらでも大丈夫です。", "はい、予約しています。", "", None,
                  "カードがいいと思います。", "かもめ便でお願いします", "鴨川に住んでいます"):
            self.assertIsNone(why(t), t)
        # 言い直しへの返事：「大丈夫です」は認める返事（決まりを当てない）・「たぶんそうです」は言い切っていないが、聞き直さずに受け取る
        # （値に「曖昧」の印を付ける＝Flow._hedged。✅ 2026-10-18 ユーザー：「yes,but 曖昧」）
        self.assertIsNone(why("大丈夫です。", policy=False, confirming=True))
        self.assertIsNone(why("たぶんそうです。", policy=False, confirming=True))
        self.assertTrue(Flow._hedged("たぶんそうです。", {}))
        self.assertFalse(Flow._hedged("はい、そうです。", {}))
        # 「わからない」の報告には、言い切っていない決まりを当てない（「たぶん分からないです」は、そのまま「わからない」）
        self.assertIsNone(why("たぶん分からないです。", reported="unknown", policy=False))

    def test_ambiguous_is_confirmed_by_meaning(self):
        f = self.flow()
        r = self.say(f, "大丈夫です。", "record_answer", question_id="Q1", condition_id="はい", value="大丈夫です")
        self.assertEqual(r["result"], "confirm_required")
        self.assertEqual(r["say"], "念のためご予約はお済みということでよろしいでしょうか？")
        self.assertEqual(r["ack"], "hai")
        self.assertNotIn("大丈夫でしょうか", r["say"])   # 相手の「大丈夫です」をそのまま聞き返さない
        r = self.say(f, "はい。", "confirm_field", question_id="Q1", result="affirmed")
        self.assertEqual((f.items["Q1"].state, f.export()["Q1"]), ("confirmed", "はい"))

    def test_hedged_reply_is_taken_with_a_mark(self):
        # ✅ 2026-10-18 ユーザー：「『していないはずですが…』『5万円くらいかなとは思いますが』なんかは、『yes,but 曖昧』のような返答にしておけば
        #    いいんじゃないですか？」⇒ 言い直しへの返事が言い切っていなければ、もう一度は聞かず、値に「曖昧」の印を付けて受け取る
        from meaning_judge import Reading
        f = self.flow()
        f.use_checks("judge")
        f.on_callee(); f.on_heard("大丈夫です。"); f.on_check("judge", Reading("はい"))
        r = f.apply("record_answer", {"question_id": "Q1", "condition_id": "はい", "value": "大丈夫です"})
        self.assertEqual(r["result"], "confirm_required")
        # 言い切っていない言葉（たぶん・はず…）が無くても、意味の判定が言い切っていないと読めば印を付ける
        f.on_callee(); f.on_heard("予約したと言えばしたんですが。"); f.on_check("judge", Reading("はい", firm=False))
        r = f.apply("confirm_field", {"question_id": "Q1", "result": "affirmed"})
        self.assertEqual(f.items["Q1"].state, "confirmed")
        # 依頼主へは、値はそのまま・別の欄にお客様の言葉（✅ 2026-10-18 ユーザー：案C）
        self.assertEqual((f.export()["Q1"], f.customer_words()), ("はい", {"Q1": "予約したと言えばしたんですが。"}))

    def test_offer_restatement_echoes_the_word(self):
        # ✅ 2026-10-18 ユーザー：「『はい、念のためパンフレットをお送りして大丈夫だということでよろしかったでしょうか？』語尾に『よろしい』が
        #    2回は違和感。相手が言ったことを聞き返した方が確か」⇒ 意味の言葉の「よろしい」を、相手の言葉に替える（語尾と同じ言葉を重ねない）
        from flowctl import Flow, Question
        from phrases import confirm, restate_words
        q = Question("Q8", "パンフレットをお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                     meanings={"はい": "パンフレットをお送りしてよろしいということ", "いいえ": "パンフレットはお送りしなくてよろしいということ"})
        f = Flow([q])
        r = self.say(f, "大丈夫です。", "record_answer", question_id="Q8", condition_id="はい", value="大丈夫です")
        self.assertEqual(r["say"], "念のためパンフレットをお送りして大丈夫だということでよろしいでしょうか？")
        self.assertEqual(restate_words("パンフレットはお送りしなくてよろしいということ", "結構です。"), "パンフレットはお送りしなくて結構だということ")
        self.assertEqual(restate_words("パンフレットをお送りしてよろしいということ", "いいです"), "パンフレットをお送りしていいということ")
        self.assertEqual(restate_words("ご予約はお済みということ", "大丈夫です。"), "ご予約はお済みということ")  # 「よろしい」が無ければそのまま
        # 語尾は、言い直す言葉と同じ言葉を使わない形だけから選ぶ
        for n in range(4):
            said = confirm("パンフレットをお送りして大丈夫だということ", "ふつう", n, meaning=True)
            self.assertEqual(said.count("大丈夫"), 1, said)

