    def test_day_fields_match_cl2(self):
        # CL-2 の 4-397 の (2)：{最短の日} を書ける（会話の側が言い方に置き換える）質問の欄の一覧（こちら＝流れの制御が置き換える1か所
        # flowctl.DAY_FIELDS（文の欄）と DAY_LISTS（文の並びの欄＝先に並べた文）・CL-2 の business_settings.DAY_FIELDS）が同じ。⛔ 2026-11-15 に
        # CL-2 の一覧が質問の文・入る一言だけで、取込の AI が {最短の日} を残した文（お知らせの文など）の業務を「書けない所に書いた」として登録
        # できなかった＝2か所の一覧のずれ（CL-2 の試験は試作を読まないので、ずれを見つけられるのはこの比べだけ）。CL-2 の版が main に入るまでは
        # CL-2 の一覧が無いので飛ばす。欄を足したら、CL-2 が足すまで CL2_PENDING に入れる。待つのは、CL-2 の質問の欄（QUESTION_KEYS）にまだ
        # 無い名前だけ（⛔ CL2_PENDING の名前をそのまま許すと、CL-2 が欄を持っているのに一覧に入れていない 4-397 のずれを見逃した＝写しで確かめた）
        import dataclasses
        from flowctl import DAY_FIELDS, DAY_LISTS, Question
        names = {f.name: f.type for f in dataclasses.fields(Question)}
        self.assertEqual(sorted(n for n in (*DAY_FIELDS, *DAY_LISTS) if n not in names), [], "質問の欄に無い名前")
        theirs = self.cl2_names("business_settings.py", "DAY_FIELDS")
        if theirs is None:
            self.skipTest("CL-2 の business_settings.DAY_FIELDS が、まだ main に無い")
        mine = set(DAY_FIELDS) | set(DAY_LISTS)
        waiting = mine - without_cl2_pending(self, mine, theirs) - (self.cl2_names("business_settings.py", "QUESTION_KEYS") or set())
        self.assertEqual((sorted(mine - waiting - theirs), sorted(theirs - mine)), ([], []), "（こちらだけ, CL-2 だけ）")

    def test_told_kinds_offers_and_reasons_match_cl2(self):
        # K-2（11-08 日本時間8時台。CL-2 の 4-229・4-234 の (a)・4-236／4-250 の頼み）：CL-2 の写しと比べる試験が無かった4つ＝申し伝える一言の種類（CL-2 の
        # call_report.TOLD_KINDS＝phrases.POINT_KINDS の鍵）・お客様の申し出（call_report.CALLBACK_OFFERS＝flowctl.OFFER_LABEL の鍵）・「わからない」「答えたくない」の
        # 理由（business_rules.DONT_KNOW_REASONS・REFUSED_REASONS＝flowctl.DONT_KNOW_LABEL・REFUSED_LABEL の鍵）。CL-2 の版が main に無い一覧は、入るまで飛ばす
        # （TOLD_KINDS は 11-08 時点で CL-2 の枝だけ）。CL-2 の LATER_INTENTS は会話の側に同じ一覧が無い（比べるものが無い＝CL-1.md 4-119）。
        # CL-2 の 4-320 の (b)：値を伺う質問の型（CL-2 の business_settings.ESTIMATE_TYPES＝flowctl.ESTIMATE_TYPES。変更の受付の期限を書ける質問）と、
        # お客様の申し出・本題の始まりの選べるもの（CL-2 の call_report.RESPONSE_POLICIES＝flowctl.POLICIES の鍵と選べるもの）も（CL-1.md 4-120）
        # CL-2 の 4-340 の Q110：「取れた」の定義（CL-2 の judge.TAKEN＝flowctl.GOT。依頼者へ渡すお客様の言葉の欄 hedged を、取れた答えのときだけ言い切っていない
        # 印と読む決まり＝こちらの earlier_hedged・CL-2 の judge.hedged_words が、この組を使う）も（CL-1.md 4-121）
        from flowctl import DONT_KNOW_LABEL, ESTIMATE_TYPES, GOT, OFFER_LABEL, POLICIES, REFUSED_LABEL
        from phrases import POINT_KINDS
        compared = []
        for path, var, mine in (("call_report.py", "TOLD_KINDS", set(POINT_KINDS)), ("call_report.py", "CALLBACK_OFFERS", set(OFFER_LABEL)),
                                ("business_rules.py", "DONT_KNOW_REASONS", set(DONT_KNOW_LABEL)), ("business_rules.py", "REFUSED_REASONS", set(REFUSED_LABEL)),
                                ("business_settings.py", "ESTIMATE_TYPES", set(ESTIMATE_TYPES)), ("judge.py", "TAKEN", set(GOT)),
                                ("call_report.py", "RESPONSE_POLICIES", None)):
            theirs = self.cl2_names(path, var)
            if theirs is None:
                continue
            if mine is None:   # 鍵と選べるもの：CL-2 の版にまだ無い鍵（CL2_PENDING）の選べるものは、ほかの一覧の名前と重なりうるので、鍵ごと外して比べる
                mine = {x for k, vs in POLICIES.items() if not (k in CL2_PENDING and k not in theirs) for x in (k, *vs)} | set(POLICIES)
            compared.append(var)
            self.assertEqual((sorted(without_cl2_pending(self, mine, theirs) - theirs), sorted(theirs - mine)), ([], []), f"{var}（こちらだけ, CL-2 だけ）")
        if not compared:
            self.skipTest("CL-2 の一覧が、まだ main に無い")

    def test_do_words_rules_match_cl2(self):
        # CL-2 の 4-202 の (a)：こちらがすることの言葉の形の決まり（こちら＝meanings の DO_END・DO_DOUBLED・MARKS と頭の言葉 QUESTION_HEADS・CL-2 の
        # business_settings の DO_WORDS_END・DO_WORDS_DOUBLED・DO_WORDS_MARKS と QUESTION_LEADS）が同じ。依頼者が書いた言葉は CL-2 の1か所だけを通り、
        # 取込の AI の言葉は先にこちらの meanings.check を通る＝決まりが食い違うと、同じ言葉が片方でだけ通る
        # CL-2 の 4-215 の (4-90 の (1))：言葉の終わりに書けない形（こちら＝meanings.BAD_END・CL-2 の business_settings.DOUBT_WORDS_BAD_END）も（CL-1.md 4-120）
        import meanings
        # 言葉の種類の決まり（meanings.DO_KINDS＝申し出かを読む Question.offered の1か所）は、文の終わりの決まり（DO_END＝CL-2 の DO_WORDS_END）を通る言葉なら
        # 必ずどれかに当たる＝どの種類にも当たらない言葉は、取込でも依頼者の言葉でも今の決まりのまま使わない（CL-2 は種類の写しを持たない。まとめ役の (H4)）
        for end in meanings.DO_END.pattern.removeprefix("(?:").split(")")[0].split("|"):
            self.assertIsNotNone(meanings.do_kind("パンフレットをお送り" + end), end)
        for mine, var in ((meanings.DO_END, "DO_WORDS_END"), (meanings.DO_DOUBLED, "DO_WORDS_DOUBLED"), (meanings.MARKS, "DO_WORDS_MARKS"),
                          (meanings.BAD_END, "DOUBT_WORDS_BAD_END")):
            theirs = self.cl2_names("business_settings.py", var)
            if theirs is None:
                self.skipTest(f"CL-2 の business_settings.{var} が、まだ main に無い")
            self.assertEqual(theirs, {mine.pattern}, var)

    def test_choice_words_do_not_start_with_question_heads(self):
        # 会話の側が言葉の前に付けうる言葉（phrases.QUESTION_HEADS＝「それでは」「はい」「承知しました」など）で始まる選択肢ごとの言葉は使わない
        # （「それではそれでは…ね？」「はい、はい…」と重なる）。CL-2 の do_words_ok と同じ決まりを、こちらがすることの言葉だけでなく、意味の言葉・いまの話の
        # 向きを伺う言葉にも当てる（同じ理由＝どの言葉も、会話の側が相づち・つなぎの言葉のあとに言う）
        from meanings import check
        q = "パンフレットをお送りしてもよろしいでしょうか？"
        for kind, w in (("do", "パンフレットをお送りさせていただきます"), ("meaning", "パンフレットをお送りしてよいということ"),
                        ("doubt", "パンフレットをお送りした方がいい")):
            self.assertTrue(check(w, q, "はい", kind), kind)
            for head in ("それでは", "はい", "承知しました"):
                self.assertFalse(check(head + w, q, "はい", kind), (kind, head))

    def test_offer_do_end_and_means_in_match_cl2(self):
        # CL-2 の 4-370 の (8)：締める前の申し出のこちらがすることの言葉の終わり（こちら phrases.OFFER_DO_END・CL-2 の business_settings.OFFER_DO_END）と、
        # ご連絡の方法の見分け方（こちら flowctl.means_in・WISH_MEANS の言葉・CL-2 の business_settings.means_in・MEANS_WORDS）が同じ。見分け方は、CL-2 の関数の文と
        # 言葉の表だけを別の名前空間で動かして、同じ名前の並びで答えを比べる（CL-2 の部品は読み込まない＝I-30）
        import ast
        import pathlib
        import unicodedata
        from flowctl import WISH_MEANS, means_in
        from phrases import OFFER_DO_END
        theirs = self.cl2_names("business_settings.py", "OFFER_DO_END")
        if theirs is None:
            self.skipTest("CL-2 の business_settings.OFFER_DO_END が、まだ main に無い")
        self.assertEqual(theirs, {OFFER_DO_END})
        src = pathlib.Path(__file__).resolve().parent.parent / "app" / "src" / "salescall" / "core" / "business_settings.py"
        tree = ast.parse(src.read_text(encoding="utf-8"))
        nodes = [n for n in tree.body if (isinstance(n, ast.FunctionDef) and n.name == "means_in")
                 or (isinstance(n, ast.Assign) and any(getattr(t, "id", None) == "MEANS_WORDS" for t in n.targets))]
        self.assertEqual(len(nodes), 2, "CL-2 の business_settings に MEANS_WORDS と means_in がある")
        space = {"unicodedata": unicodedata}
        exec(compile(ast.Module(body=nodes, type_ignores=[]), str(src), "exec"), space)
        self.assertEqual({k: set(v) for k, v in space["MEANS_WORDS"].items()}, {k: set(ws) for k, (_, ws, _) in WISH_MEANS.items()})
        names = [w for _, ws, _ in WISH_MEANS.values() for w in ws] + ["オンライン説明", "LINEかメール", "ｚｏｏｍ", "電話・FAX", "郵便でお送り", "セミナー参加", "訪問"]
        self.assertEqual([space["means_in"](n) for n in names], [means_in(n) for n in names])

