        b = OtherCompanyClueSendWayTest().business()
        earlier = {"Q1": {"state": "accepted", "condition": "はい"},
                   "Q2": {"state": "accepted", "condition": NONE, "whole_fact": {**self.WHOLE, "answer": "どれも要らない"}}}
